import math
def sigmoid(x): return 1/(1+math.exp(-x))
W1=[[0.5,0.3],[0.2,0.8]];b1=[0.1,-0.1];W2=[0.6,0.9];b2=0.05
def forward(h,s):
    x=[h/10,s/100];hid=[sigmoid(W1[j][0]*x[0]+W1[j][1]*x[1]+b1[j]) for j in range(2)]
    return sigmoid(W2[0]*hid[0]+W2[1]*hid[1]+b2)
for h,s in[(8,72),(2,45),(6,65)]:
    print(f"hours={h} score={s} → pass prob={forward(h,s):.1%}")
